package com.shopsphere.model;import com.fasterxml.jackson.annotation.JsonIgnoreProperties;import jakarta.persistence.*;import java.time.LocalDateTime;import java.util.*;@Entity @Table(name="shop_orders") public class ShopOrder{@Id @GeneratedValue(strategy=GenerationType.IDENTITY)private Long id;@ManyToOne(optional=false)@JsonIgnoreProperties({"password"})private AppUser user;@OneToMany(mappedBy="order",cascade=CascadeType.ALL,orphanRemoval=true)@JsonIgnoreProperties("order")private List<OrderItem> items=new ArrayList<>();private Double totalAmount=0.0;@Enumerated(EnumType.STRING)private OrderStatus status=OrderStatus.PLACED;private String paymentMethod="DEMO_ON_DELIVERY";private LocalDateTime createdAt=LocalDateTime.now();public ShopOrder(){}public Long getId(){return id;}public AppUser getUser(){return user;}public void setUser(AppUser x){user=x;}public List<OrderItem> getItems(){return items;}public void setItems(List<OrderItem>x){items=x;}public Double getTotalAmount(){return totalAmount;}public void setTotalAmount(Double x){totalAmount=x;}public OrderStatus getStatus(){return status;}public void setStatus(OrderStatus x){status=x;}public String getPaymentMethod(){return paymentMethod;}public void setPaymentMethod(String x){paymentMethod=x;}public LocalDateTime getCreatedAt(){return createdAt;}}